<script lang="ts">import Timeline from '@fex-design/svelte/primitive/timeline';import Item from '@fex-design/svelte/primitive/timeline-item';import Indicator from '@fex-design/svelte/primitive/timeline-indicator';import Content from '@fex-design/svelte/primitive/timeline-content';import Opposite from '@fex-design/svelte/primitive/timeline-opposite';import Card from '@fex-design/svelte/ui/card';const labels=['Ordered','Paid','Shipped','Delivered']</script>
